############################################# ### Generated from PreTeXt source ### ### https://pretextbook.org ### ############################################# ## DBsubject() ## DBchapter() ## DBsection() ## Level() ## KEYWORDS() ## TitleText1() ## EditionText1() ## AuthorText1() ## Section1(not reported) ## Problem1(1.8.6.41) ## Author() ## Institution() ## Language(en-US)
DOCUMENT();
############# # Load Macros #############
loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "PCCmacros.pl", "parserNumberWithUnits.pl", "parserLinearRelation.pl", "randomPerson.pl", "ORCCA.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
####### # Setup #######
$name = randomPerson(); $rate = random(50,65); $speed = NumberWithUnits("$rate mph"); $I = list_random(5,10,15,20,25,35,40,55,65,70,75,80,90,95); $initial = random(100,200); $final = $initial + random(80,250); Context("LinearRelation")->variables->are(t => 'Real'); $equation = LinearRelation("$initial + $rate t = $final");
############################# # Exercise Group Introduction #############################
BEGIN_PGML Write an equation to model the scenario. There is no need to solve the equation.
END_PGML
###### # Body ######
BEGIN_PGML [$name] is driving with an average speed of [`[$speed]`] on Interstate-[$I]. [$name->Subject] [$name->verb('look')] out the window and [$name->verb('see')] mile marker [$initial] pass by. How long will it take [$name->object] to reach [$name->possessive] destination, which is at mile marker [$final]? Write an equation to model this scenario. There is no need to solve it.
[@KeyboardInstructions('Use [|t|]* as the variable.')@]**
[_]{$equation}{20}
END_PGML
############# # End Problem #############
ENDDOCUMENT();
